// ============================================================================
// DigRF_apb: APB4 register wrapper around DigRF_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/DigRF.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/DigRF.md
// ============================================================================
module DigRF_apb (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic tx_p,
  input logic rx_p,
  output logic reg_we,
  output logic reg_re,
  output logic [7:0] reg_addr,
  output logic [7:0] reg_wdata,
  input logic [7:0] reg_rdata,
  input logic dtx_valid,
  output logic dtx_ready,
  input logic [7:0] dtx_data,
  input logic [2:0] dtx_size,
  input logic [1:0] dtx_chan,
  output logic drx_valid,
  output logic [7:0] drx_data,
  output logic drx_sof,
  output logic drx_eof,
  output logic [1:0] drx_chan,
  output logic drx_abort
);
  localparam logic [31:0] ID_VALUE = 32'h44460200;

  // ---------------- core ----------------
  logic [3:0]    c_cfg_sync;
  logic [7:0]    c_cfg_hold;
  logic [7:0]    c_cfg_timeout;
  logic          c_ctl_valid;
  logic          c_ctl_ready;
  logic          c_ctl_rd;
  logic [7:0]    c_ctl_addr;
  logic [7:0]    c_ctl_wdata;
  logic          c_rsp_valid;
  logic [7:0]    c_rsp_data;
  logic          c_rsp_timeout;
  logic          c_int_valid;
  logic          c_int_ready;
  logic [4:0]    c_int_vec;
  logic          c_int_rx;
  logic [4:0]    c_int_rx_vec;
  logic          c_tx_on;
  logic          c_rx_locked;
  logic          c_err_code;
  logic          c_err_frame;
  logic          c_tx_underrun;
  DigRF_top u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .tx_p(tx_p),
    .rx_p(rx_p),
    .cfg_sync(c_cfg_sync),
    .cfg_hold(c_cfg_hold),
    .cfg_timeout(c_cfg_timeout),
    .ctl_valid(c_ctl_valid),
    .ctl_ready(c_ctl_ready),
    .ctl_rd(c_ctl_rd),
    .ctl_addr(c_ctl_addr),
    .ctl_wdata(c_ctl_wdata),
    .rsp_valid(c_rsp_valid),
    .rsp_data(c_rsp_data),
    .rsp_timeout(c_rsp_timeout),
    .reg_we(reg_we),
    .reg_re(reg_re),
    .reg_addr(reg_addr),
    .reg_wdata(reg_wdata),
    .reg_rdata(reg_rdata),
    .int_valid(c_int_valid),
    .int_ready(c_int_ready),
    .int_vec(c_int_vec),
    .int_rx(c_int_rx),
    .int_rx_vec(c_int_rx_vec),
    .dtx_valid(dtx_valid),
    .dtx_ready(dtx_ready),
    .dtx_data(dtx_data),
    .dtx_size(dtx_size),
    .dtx_chan(dtx_chan),
    .drx_valid(drx_valid),
    .drx_data(drx_data),
    .drx_sof(drx_sof),
    .drx_eof(drx_eof),
    .drx_chan(drx_chan),
    .drx_abort(drx_abort),
    .tx_on(c_tx_on),
    .rx_locked(c_rx_locked),
    .err_code(c_err_code),
    .err_frame(c_err_frame),
    .tx_underrun(c_tx_underrun)
  );

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [10:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd11) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- registers ----------------
  logic [11:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [19:0] r_CFG;   // 12'h014 CFG
  logic [16:0] h_CTL;   // 12'h018 CTL holding register
  logic [7:0] h_RSP;   // 12'h01C RSP holding register
  logic [4:0] h_INT_TX;   // 12'h020 INT_TX holding register
  logic [4:0] h_INT_RX;   // 12'h024 INT_RX holding register
  logic full_CTL;
  logic avail_RSP;
  logic full_INT_TX;
  logic avail_INT_RX;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CFG <= 20'h40102;
      h_CTL <= '0;
      h_RSP <= '0;
      h_INT_TX <= '0;
      h_INT_RX <= '0;
      full_CTL <= 1'b0;
      avail_RSP <= 1'b0;
      full_INT_TX <= 1'b0;
      avail_INT_RX <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[11:0] & wmask[11:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[11:0]) | (PWDATA[11:0] & wmask[11:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CFG <= (r_CFG & ~wmask[19:0]) | (PWDATA[19:0] & wmask[19:0]);
      if (wr && hit[6] && !full_CTL) h_CTL <= (h_CTL & ~wmask[16:0]) | (PWDATA[16:0] & wmask[16:0]);
      if (wr && hit[6] && !full_CTL) full_CTL <= 1'b1;
      else if (full_CTL && c_ctl_ready) full_CTL <= 1'b0;
      if (c_rsp_valid && (!avail_RSP || (rd && hit[7]))) begin
        h_RSP[7:0] <= c_rsp_data[7:0];
        avail_RSP <= 1'b1;
      end else if (rd && hit[7]) avail_RSP <= 1'b0;
      if (wr && hit[8] && !full_INT_TX) h_INT_TX <= (h_INT_TX & ~wmask[4:0]) | (PWDATA[4:0] & wmask[4:0]);
      if (wr && hit[8] && !full_INT_TX) full_INT_TX <= 1'b1;
      else if (full_INT_TX && c_int_ready) full_INT_TX <= 1'b0;
      if (c_int_rx && (!avail_INT_RX || (rd && hit[9]))) begin
        h_INT_RX[4:0] <= c_int_rx_vec[4:0];
        avail_INT_RX <= 1'b1;
      end else if (rd && hit[9]) avail_INT_RX <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_cfg_sync = r_CFG[3:0];
  assign c_cfg_hold = r_CFG[11:4];
  assign c_cfg_timeout = r_CFG[19:12];
  assign c_ctl_wdata[7:0] = h_CTL[7:0];
  assign c_ctl_addr[7:0] = h_CTL[15:8];
  assign c_ctl_rd = h_CTL[16:16];
  assign c_int_vec[4:0] = h_INT_TX[4:0];
  assign c_ctl_valid = full_CTL;
  assign c_int_valid = full_INT_TX;

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_rsp_timeout;
    irq_set[1] = c_err_code;
    irq_set[2] = c_err_frame;
    irq_set[3] = c_tx_underrun;
    irq_set[4] = full_CTL & c_ctl_ready;
    irq_set[5] = wr & (hit[6]) & full_CTL;
    irq_set[6] = c_rsp_valid & (~avail_RSP | (rd & hit[7]));
    irq_set[7] = c_rsp_valid & avail_RSP & ~(rd & hit[7]);
    irq_set[8] = full_INT_TX & c_int_ready;
    irq_set[9] = wr & (hit[8]) & full_INT_TX;
    irq_set[10] = c_int_rx & (~avail_INT_RX | (rd & hit[9]));
    irq_set[11] = c_int_rx & avail_INT_RX & ~(rd & hit[9]);
  end
  assign irq = |(irq_status & irq_enable);
  wire [3:0] flags = {avail_INT_RX, full_INT_TX, avail_RSP, full_CTL};

  // ---------------- read mux ----------------
  logic [31:0] rdata;
  always_comb begin
    rdata = '0;
    case (PADDR[11:2])
      10'd0: rdata = ID_VALUE;
      10'd1: rdata = 32'(irq_status);
      10'd2: rdata = 32'(irq_enable);
      10'd3: rdata = 32'(flags);
      10'd4: rdata = scratch;
      10'd5: rdata = 32'(r_CFG);
      10'd6: rdata = 32'(h_CTL);
      10'd7: rdata = 32'(h_RSP);
      10'd8: rdata = 32'(h_INT_TX);
      10'd9: rdata = 32'(h_INT_RX);
      10'd10: rdata = 32'({c_rx_locked, c_tx_on});
      default: rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? rdata : '0;
endmodule
